from pathlib import Path
from html import escape as esc
import json,zipfile
from commerce_data import PRODUCTS
ROOT=Path(__file__).resolve().parents[1]
colours={'studio':('#f0eadf','#191817','#c67f53'),'stay':('#ece5d7','#25382e','#92754c'),'ink':('#151514','#f1eadd','#c9a56d'),'orbit':('#10181b','#dfeae4','#b8e780'),'table':('#471f24','#fae8cd','#ef8c5f'),'launch':('#f3e9e1','#252125','#9675b0')}
for p in PRODUCTS:
 bg,ink,accent=colours[p['theme']];name=p['short'];tokens={'background':bg,'foreground':ink,'accent':accent,'radius':'8px','spacing-unit':'8px'}
 cards=''.join('<article><span>0'+str(i+1)+'</span><h3>'+esc(t)+'</h3><p>Replace this sample copy with the details, work and imagery that make your brand yours.</p></article>' for i,t in enumerate({'studio':['Brand direction','Digital experiences','Creative campaigns'],'stay':['Stay a little longer','Explore the destination','Make it your own'],'ink':['Selected work','The artist','The studio'],'orbit':['Campaign overview','Team tasks','Reporting context'],'table':['The menu','The occasion','The venue'],'launch':['Colour system','Type and rhythm','Interface patterns']}[p['theme']]))
 title={'studio':'Ideas with an independent spirit.','stay':'A slower kind of escape.','ink':'Make your mark.','orbit':'A clearer working day.','table':'Good food. Better company.','launch':'Give the next idea a visual language.'}[p['theme']]
 extra='<div class="bars" aria-label="Illustrative chart"><i style="height:25%"></i><i style="height:50%"></i><i style="height:35%"></i><i style="height:75%"></i><i style="height:60%"></i><i style="height:90%"></i></div>' if p['theme']=='orbit' else '<div class="art" aria-hidden="true"><span>'+name+'</span><i></i></div>'
 doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'''+name+''' — PRIMO sample starter</title><style>
 :root{--bg:'''+bg+''';--ink:'''+ink+''';--accent:'''+accent+'''}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,sans-serif}a{color:inherit;text-decoration:none}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:25px 6%;border-bottom:1px solid color-mix(in srgb,var(--ink) 20%,transparent)}header strong{letter-spacing:.15em}nav{display:flex;gap:20px;font-size:12px}.hero{padding:65px 6%;display:grid;grid-template-columns:1.15fr .85fr;gap:50px;align-items:center}.eyebrow{text-transform:uppercase;letter-spacing:.2em;font-size:10px}h1{font-size:clamp(38px,6vw,82px);line-height:1;letter-spacing:-.06em;margin:25px 0;font-weight:800}p{font-size:14px;line-height:1.8;max-width:500px;opacity:.8}.button{display:inline-block;background:var(--ink);color:var(--bg);padding:15px 22px;border-radius:5px;font-size:12px;margin-top:15px}.art{height:400px;position:relative;overflow:hidden;background:linear-gradient(145deg,var(--accent),var(--ink));border-radius:5px}.art span{position:absolute;left:-10px;bottom:10px;color:var(--bg);font-weight:800;font-size:100px;letter-spacing:-.08em;writing-mode:vertical-rl;opacity:.6}.art i{position:absolute;inset:15%;border:1px solid var(--bg);border-radius:50%;transform:rotate(-35deg);opacity:.5}.section{padding:65px 6%;border-top:1px solid color-mix(in srgb,var(--ink) 20%,transparent)}h2{font-size:clamp(27px,4vw,48px);letter-spacing:-.045em}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}article{border:1px solid color-mix(in srgb,var(--ink) 25%,transparent);padding:25px}article span{font-size:10px;color:var(--accent)}h3{font-size:22px;letter-spacing:-.03em}.bars{height:350px;display:flex;align-items:flex-end;gap:14px;padding:30px;background:color-mix(in srgb,var(--ink) 7%,transparent)}.bars i{background:var(--accent);flex:1;border-radius:5px 5px 0 0}details{padding:18px 0;border-top:1px solid color-mix(in srgb,var(--ink) 20%,transparent)}summary{cursor:pointer}footer{padding:25px 6%;font-size:10px;opacity:.6}.sample-note{font-size:10px;letter-spacing:.03em}@media(max-width:650px){.hero{grid-template-columns:1fr;padding-top:45px}.art{height:250px}.cards{grid-template-columns:1fr}nav{gap:12px;font-size:10px}}
 </style></head><body><header><strong>'''+name+'''</strong><nav><a href="#explore">Explore</a><a href="#details">Details</a><a href="#contact">Contact</a></nav></header><main><section class="hero"><div><div class="eyebrow">An independent digital starter</div><h1>'''+title+'''</h1><p>'''+esc(p['description'])+'''</p><a class="button" href="#explore">Explore the sample ↗</a><p class="sample-note">PRIMO sample starter · Replace sample content before launch.</p></div>'''+extra+'''</section><section class="section" id="explore"><div class="eyebrow">The starting point</div><h2>Room for your point of view.</h2><div class="cards">'''+cards+'''</div></section><section class="section" id="details"><h2>Made to adapt.</h2><details><summary>What is included?</summary><p>A self-contained HTML page with editable CSS. This is an evaluation starter, with no production integrations.</p></details><details><summary>How do I customise it?</summary><p>Edit the text, colours and layout in index.html. Add photography you have permission to use and connect your own contact or booking tools.</p></details></section><section class="section" id="contact"><h2>Make it yours.</h2><p>This sample contact section is ready for your own details. No contact endpoint or booking service is connected.</p><a class="button" href="#explore">Back to the sample ↑</a></section></main><footer>'''+name+''' / Created as a PRIMO evaluation starter. Not a finished commercial product.</footer></body></html>'''
 path=ROOT/'assets/previews'/p['id'];path.mkdir(parents=True,exist_ok=True);(path/'index.html').write_text(doc)
 readme=f'''# {p['name']} — evaluation sample

This original PRIMO HTML/CSS starter is provided for internal evaluation and demonstration. It is not a production-ready, purchased template and does not confer a commercial resale licence. Product pricing in the marketplace is illustrative.

Files: index.html, design-tokens.json, README.md.

Open index.html or serve it with a static HTTP server. Edit the content and CSS in the HTML. Replace sample text and designed image placeholders with your own work. No third-party photography or client artwork is bundled. There is no payment, booking, authentication or form backend. Review accessibility, responsiveness and implementation before production use.

A commercial product licence, support policy and final deliverables need to be defined before selling the finished version.
'''
 with zipfile.ZipFile(ROOT/'assets/downloads'/(p['id']+'-sample.zip'),'w',zipfile.ZIP_DEFLATED) as z:z.writestr('index.html',doc);z.writestr('design-tokens.json',json.dumps(tokens,indent=2));z.writestr('README.md',readme)
(ROOT/'assets/catalogue.js').write_text('window.PRIMO_CATALOGUE='+json.dumps(PRODUCTS,ensure_ascii=False)+';\n')
(ROOT/'assets/downloads/sample-project-brief.txt').write_text('PRIMO DEMO PROJECT BRIEF\n\nFictional client: Sample Studio\nProject: Website refresh\nGoal: demonstrate a clear project journey, design approvals and handover.\nScope: discovery, wireframes, design review, build and launch preparation.\nThis file is an example only, not a live client brief.\n')
print('Six original HTML evaluation starters and downloadable sample ZIPs generated.')
